{
 "contract_type": "msa",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Copperline Software GmbH"],
   "quote": "by and between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Copperline Software GmbH (\"Copperline\")"
  },
  "counterparty": {
   "value": "Copperline Software GmbH",
   "quote": "and Copperline Software GmbH (\"Copperline\")"
  },
  "effective_date": {
   "value": "2026-02-14",
   "quote": "entered into as of 14th day of February, 2026 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 36,
   "quote": "continue for a period of three (3) years"
  },
  "auto_renewal": {
   "value": true,
   "quote": "the Agreement renews automatically for additional twelve-month terms"
  },
  "renewal_notice_days": {
   "value": 30,
   "quote": "a Party must notify the other no later than thirty (30) days before the renewal date"
  },
  "governing_law": {
   "value": "California",
   "quote": "the laws of the State of California"
  },
  "liability_cap": {
   "value": "unlimited",
   "quote": "NEITHER PARTY'S LIABILITY UNDER THIS AGREEMENT SHALL BE LIMITED IN AMOUNT"
  },
  "payment_terms_days": {
   "value": 30,
   "quote": "Payment terms are Net 30."
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": true,
   "quote": "Either Party may terminate this Agreement for convenience upon thirty (30) days' prior written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Tobias Brandt",
   "email": "tobias.brandt@copperline.example",
   "title": "Geschäftsführer",
   "party": "Copperline Software GmbH"
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "unlimited_liability",
   "severity": "high",
   "message": "Liability is uncapped for both parties, so Northwind Labs has unlimited exposure to Copperline's claims (and vice versa).",
   "quote": "NOTHING IN THIS AGREEMENT LIMITS EITHER PARTY'S LIABILITY, AND NEITHER PARTY'S LIABILITY UNDER THIS AGREEMENT SHALL BE LIMITED IN AMOUNT."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The agreement has no confidentiality provision, so Northwind's confidential information shared with Copperline is not contractually protected.",
   "quote": "This Agreement constitutes the entire agreement between the Parties and supersedes all prior discussions relating to its subject matter."
  },
  {
   "id": "auto_renewal_opt_out_window",
   "severity": "medium",
   "message": "The agreement renews automatically for 12-month terms unless notice is given 30 days before the renewal date, so a missed deadline locks in another year (subject to the 30-day termination for convenience right).",
   "quote": "the Agreement renews automatically for additional twelve-month terms; to opt out, a Party must notify the other no later than thirty (30) days before the renewal date."
  },
  {
   "id": "fees_undefined",
   "severity": "medium",
   "message": "Fees are not set in the MSA and are deferred to Statements of Work, so there is no price or spending cap at the agreement level.",
   "quote": "Fees for the Services are set out in each Statement of Work."
  },
  {
   "id": "broad_either_party_termination",
   "severity": "low",
   "message": "Copperline may terminate for convenience on 30 days' notice, which could disrupt services Northwind relies on.",
   "quote": "Either Party may terminate this Agreement for convenience upon thirty (30) days' prior written notice."
  },
  {
   "id": "indemnity_one_sided_vague",
   "severity": "low",
   "message": "The indemnity favors Northwind but is vague, with no defense obligation, procedure or definition of covered claims.",
   "quote": "Copperline shall indemnify and hold harmless Northwind from third-party claims arising from the Services."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a three-year Master Services Agreement between Northwind Labs, Inc. and Copperline Software GmbH, effective February 14, 2026, auto-renewing for 12-month terms and governed by California law. Liability is unlimited for both sides, either party can terminate on 30 days' notice, and fees and confidentiality terms are not addressed in the MSA itself."
}
